<section class="section container"><div class="section-heading"><div><div class="eyebrow">GESTÃO DE CONTEÚDO</div><h1>Projetos acadêmicos</h1><p><?=count($rows)?> registros encontrados no banco.</p></div><a class="button" href="<?=url('admin/projetos/novo')?>">+ Novo projeto</a></div><form class="admin-search" method="get"><label for="admin-q">Pesquisar projetos pelo título</label><div><input name="q" id="admin-q" value="<?=e($q)?>" type="search"><button class="button">Pesquisar</button></div></form><div class="table-wrap"><table><thead><tr><th>Projeto</th><th>Edição</th><th>Situação</th><th>Destaque</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['titulo'])?></strong><small>#<?=$r['id']?></small></td><td><?=e($r['edicao'])?></td><td><span class="status <?=e($r['situacao'])?>"><?=e($r['situacao'])?></span></td><td><?=$r['destaque']?'Sim':'—'?></td><td class="actions"><a href="<?=url('admin/projetos/'.$r['id'])?>">Editar</a><?php if($r['situacao']==='publicado'):?><a href="<?=url('projeto/'.$r['id'])?>">Ver</a><?php endif;?><?php if($user['perfil']==='administrador'):?><form method="post" action="<?=url('admin/projetos/'.$r['id'].'/excluir')?>"><?=csrfField()?><button class="danger-link" data-confirm="Excluir definitivamente o projeto e todos os materiais?">Excluir</button></form><?php endif;?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5">Nenhum projeto encontrado.</td></tr><?php endif;?></tbody></table></div></section>
